pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        vm.roll(1);
        vm.warp(10);
        vm.deal(address(this), 10 ether);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "fallback call failed");
        assertEq(address(c).balance, 10 ether);
    }
}
